import sys; sys.path.insert(0, '/workspace/site/scripts/guides')
from ghelp import *
GUIDES = []
A = GUIDES.append
AD = dict(svc='ad')

A(mk('meta-ad-payment-declined-fix',
 'Meta ads payment failed or declined: how to get ads running again',
 'Meta Ads Payment Failed or Declined? Fix It',
 'A failed payment can pause your Meta ads. Find out why it was declined, how to pay the balance and what to check if payments keep failing.',
 'ads', 'Billing', None,
 'open Ads Manager, go to Billing & payments, pick the affected ad account, add or fix a payment method and choose Pay now. Ads usually resume once the balance is paid.',
 'A declined payment isn’t a policy ban, but it can look like one because ads stop. The fix is nearly always in billing, so start there before you appeal anything.',
 [('first', 'What to do first',
   '<p>Look for the “Action required” banner in Ads Manager or an email about a failed payment. Note the amount and the date. Then check whether your <strong>ad account itself is disabled</strong> (a policy matter) or only <strong>paused for payment</strong>. Billing problems and policy problems have different fixes, and mixing them up wastes days.</p>'),
  ('s1', 'Step 1: Open the billing screen',
   '<p>In Ads Manager, open <em>Billing & payments</em>, then select the affected ad account if you have several. You’ll see the outstanding balance, recent charges and the payment methods on file. Meta’s help pages describe this as the place to pay manually.</p>'),
  ('s2', 'Step 2: Add a valid payment method',
   '<p>Add a card or other method that works in your country and currency, then choose <em>Pay now</em>. If your card was declined, check the expiry date, the billing address, whether the card allows online international purchases, and whether it has an available limit. Some banks decline ad charges as unusual, so a quick call can help.</p>'),
  ('s3', 'Step 3: Check payment restrictions',
   '<p>If payments are blocked beyond a normal decline, Meta’s help center describes payment restrictions and explains what the banner means. Follow the steps shown for your account; they vary by country and payment type.</p>'),
  ('s4', 'Step 4: Wait for ads to resume',
   '<p>Meta says ads can resume after payment clears and may make up some of the delivery time lost. Check the campaign status afterwards, because a campaign can still be turned off, rejected or out of schedule.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t add many cards in quick succession.</strong> Repeated failed attempts can deepen the block.</li><li><strong>Don’t create a new ad account just to skip a balance.</strong> It won’t clear what you owe and can raise flags.</li><li><strong>Don’t share card details with “billing helpers”</strong> who contact you.</li></ul>'),
  ('after', 'Preventing repeat failures',
   '<p>Keep a backup payment method on every ad account, set a spending threshold you can afford and make sure the billing name and address match the card. Review billing weekly if you run large daily budgets, and set a calendar reminder when your card expires.</p>')],
 [('Why was my card declined when it has funds?', 'Banks can decline for fraud checks, online-payment settings or address mismatches. Check with your bank and the billing details on the account.'),
  ('Will Meta restore the missed delivery?', 'Meta’s help pages say it may make up lost delivery time after payment, but doesn’t promise how.'),
  ('Is a payment decline the same as a ban?', 'No. A decline pauses ads for billing. A disabled ad account is a policy decision with a separate appeal.')],
 [('Meta Business Help: Fix failed payments', 'https://www.facebook.com/business/help/268196136699959'), ('Meta Business Help: Payment restrictions', 'https://www.facebook.com/business/help/1256440956255650'), ('Meta Business Help: Bank declined payment', 'https://www.facebook.com/business/help/204262623014330')],
 [('/guides/meta-ad-account-disabled-payment/', 'Ad account disabled and payments'), ('/guides/meta-ad-account-restricted/', 'Ad account restricted'), ('/guides/meta-account-quality-status-walkthrough/', 'Account Quality walkthrough')],
 ['/guides/meta-ad-account-disabled-payment/', '/guides/meta-ad-account-restricted/'],
 'My Meta ads payment failed and my ads stopped. Can you help me work out what is wrong?', 'Meta ads payment failed',
 ('Ads paused?', 'Tell us what the banner says', 'Send us the message in Billing and we’ll tell you whether it’s payment or policy.'),
 ('Not sure which one it is?', 'We’ll help you work it out', 'Message us the ad account ID and what you see. We use official routes only.'),
 **AD))

A(mk('meta-ad-rejected-request-review',
 'Meta ad rejected: how to read the reason and request a review',
 'Meta Ad Rejected? How to Request a Review',
 'Understand why your ad was rejected, how to find the policy, edit or request a review, and what to leave alone while a review is pending.',
 'ads', 'Ad review', None,
 'open the rejected ad in Ads Manager, read the policy named, then either fix and resubmit or use Request review. Don’t edit the ad while a review is pending.',
 'Most ad rejections are about a specific issue in the creative, text or landing page. Reading the reason carefully is the difference between a quick fix and a loop of rejections.',
 [('first', 'What to do first',
   '<p>Don’t republish immediately. Open the ad in Ads Manager, click the red alert or the <em>Ad disapproved</em> label and read the full reason. Write down the policy name and the part of the ad it refers to, whether that’s the image, the text, the targeting or the landing page.</p>'),
  ('s1', 'Step 1: Find the policy',
   '<p>Meta’s Advertising Standards pages explain each policy with examples. Search the policy name from your rejection and read the section on what’s not allowed. Compare your ad line by line, including the headline, primary text, image text and website.</p>'),
  ('s2', 'Step 2: Decide whether to fix or dispute',
   '<p>If the issue is real, edit the ad to correct it and resubmit. That’s faster than waiting for a review. If you’re confident the ad follows the policy, request a review. Choosing the wrong path is the common mistake: disputing something that’s plainly against the rules rarely succeeds, and fixing something that’s allowed means changing your ad needlessly.</p>'),
  ('s3', 'Step 3: Request the review',
   '<p>You can request review from Ads Manager on the ad itself, or from Account Quality or Business Support Home, where an ad account’s status overview lets you select the account and choose <em>Request review</em>. Meta aims to review requests quickly and says on its pages that decisions often arrive within about a couple of days, but it doesn’t promise a time.</p>'),
  ('s4', 'Step 4: Leave the ad alone while it’s under review',
   '<p>Editing a pending ad can restart or cancel the review. Duplicate it if you want to test a fix at the same time, but don’t touch the original.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t keep resubmitting unchanged ads.</strong> Repeated violations can affect the ad account’s standing.</li><li><strong>Don’t hide the issue</strong> using tricks such as cloaked landing pages. Meta treats circumvention seriously.</li><li><strong>Don’t blame the reviewer in the request.</strong> Stick to why the ad follows the policy.</li></ul>'),
  ('after', 'Learning from the pattern',
   '<p>If a certain topic keeps getting rejected, the issue is likely in how you describe it rather than the item. Rewrite in plain language and avoid assumptions about the viewer. Keep a log of rejections and what fixed them for your team.</p>')],
 [('How long does an ad review take?', 'Meta says it aims to decide most review requests within about 48 hours but doesn’t promise a time. Complex ones can take longer.'),
  ('Can I appeal every rejection?', 'You can request a review for most. If the ad clearly breaks a policy, editing it is usually better.'),
  ('Does a rejected ad hurt my account?', 'Repeated rejections can affect account standing. Check Account Quality to see.')],
 [('Meta Business Help: Troubleshoot a rejected ad', 'https://www.facebook.com/business/help/1210227555661027'), ('Meta Business Help: Request a review', 'https://www.facebook.com/business/help/254088759757736'), ADS],
 [('/guides/meta-ads-landing-page-rejected/', 'Landing page rejected'), ('/guides/meta-account-quality-status-walkthrough/', 'Account Quality walkthrough'), ('/guides/meta-ads-health-wellness-personal-attributes/', 'Health and personal attributes')],
 ['/guides/meta-ad-account-restricted/', '/ad-account-policy-violation-appeal/'],
 'My Meta ad was rejected and I need help working out whether to edit or request a review', 'Meta ad rejected',
 ('Ad rejected?', 'Send us the reason', 'Share the policy named in the rejection and we’ll tell you whether we’d edit or request review.'),
 ('Stuck in a loop?', 'We’ll look at it with you', 'Message us the ad account ID and the rejection text. We use official routes.'),
 **AD))

A(mk('meta-domain-verification-steps',
 'Meta domain verification step by step: meta tag, HTML file or DNS',
 'Meta Domain Verification: Meta Tag, HTML File or DNS',
 'How to verify your domain in Meta Business Suite using a meta tag, HTML file or DNS TXT record, and how to fix the usual errors.',
 'ads', 'Domain', None,
 'in Business Suite go to Settings, then Brand safety, then Domains. Add your root domain and verify with a meta tag, an HTML file or a DNS TXT record.',
 'Domain verification proves your business owns a website. It matters for link ownership and some ad features. Most failures come from adding the code in the wrong place or verifying before DNS has updated.',
 [('first', 'What to do first',
   '<p>Decide who will make the change. You need access to either your website’s files or your domain’s DNS settings. If your site is built on a hosted platform, check whether it has a built-in field for Meta verification. You also need full control of the business portfolio to add domains.</p>'),
  ('s1', 'Step 1: Add the domain',
   '<p>Open Meta Business Suite, go to <em>Settings</em>, then <em>Brand safety</em>, then <em>Domains</em>, and choose <em>Add</em>. Enter your <strong>root domain</strong> such as example.com, not a page address or a subdomain, and follow the prompts.</p>'),
  ('s2', 'Step 2: Choose a method',
   '<ul><li><strong>Meta tag:</strong> paste the supplied tag into the head section of your home page.</li><li><strong>HTML file:</strong> upload the provided file to your site’s root so it opens at the address Meta shows.</li><li><strong>DNS TXT record:</strong> add the TXT record to your domain’s DNS zone.</li></ul>'
   '<p>Pick the method you can complete today. The tag is easiest on many website builders; DNS is more durable if you change site platforms often.</p>'),
  ('s3', 'Step 3: Verify',
   '<p>Return to Meta and choose <em>Verify domain</em>. DNS changes can take time to propagate, so if it fails right after you add a record, wait and try again later. If a meta tag fails, check that it’s on the page Meta can read, not behind a login, and that caching hasn’t kept an old copy.</p>'),
  ('s4', 'Step 4: Troubleshoot',
   '<p>Common causes include verifying a subdomain instead of the root domain, a record added to the wrong DNS zone, a site that redirects the root domain to a different one, and a developer tool that strips the tag. Meta’s developer documentation on domain verification includes a debugging guide for these.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t verify a domain you don’t own</strong> or ask someone to verify yours on their portfolio without agreeing who owns it.</li><li><strong>Don’t delete the record the same minute you click verify.</strong> Wait until Meta confirms success.</li><li><strong>Don’t paste the code from someone else’s account.</strong> Each code is unique to your portfolio.</li></ul>'),
  ('after', 'After it’s verified',
   '<p>Meta’s help pages say you can remove the tag or record afterwards, but many teams leave it in place so the verification isn’t lost during a site rebuild. Note down who owns the domain registration, and keep the login in a shared password manager.</p>')],
 [('Do I need to verify a domain to run ads?', 'Not always. It depends on the features you use. Meta’s help page lists where it’s needed.'),
  ('Can I verify more than one domain?', 'Yes, each root domain is added and verified separately.'),
  ('Why does verification fail even though the tag is there?', 'The page may be cached, redirected or blocked. Check the live source in a private window.')],
 [('Meta Business Help: Verify your domain', 'https://www.facebook.com/business/help/321167023127050'), ('Meta for Developers: Domain verification', 'https://developers.facebook.com/docs/sharing/domain-verification'), BIZ_HELP],
 [('/guides/meta-business-portfolio-two-factor/', 'Business portfolio two-factor'), ('/guides/meta-ad-account-restricted/', 'Ad account restricted'), ('/meta-business-verification-rejected/', 'Business verification rejected')],
 ['/meta-business-verification-rejected/', '/guides/meta-business-portfolio-restricted/'],
 'I need help verifying my domain in Meta Business Suite', 'Meta domain verification',
 ('Verification failing?', 'Tell us the method', 'Tell us whether you used a tag, file or DNS and what the error says.'),
 ('Need a second pair of eyes?', 'We’ll check it with you', 'Message us the domain and what you’ve tried. No logins needed.'),
 **AD))

A(mk('meta-business-portfolio-two-factor',
 'Require two-factor authentication for everyone in your Meta business portfolio',
 'Require Two-Factor for Your Meta Business Portfolio',
 'How to turn on the business portfolio security setting that requires two-factor authentication for all people, and what to tell your team first.',
 'ads', 'Security', None,
 'a full-control admin opens Settings, then Business portfolio info, then Business options, and sets two-factor authentication to Everyone. Tell your team first.',
 'One compromised login can put your Pages, ad accounts and payment methods at risk. Requiring two-factor authentication for everyone in the portfolio is one of the strongest protections you can add.',
 [('first', 'What to do first',
   '<p>Check who has access. Open the people list in your business settings and remove anyone who doesn’t need it. Then tell your team the change is coming and why, because anyone without two-factor authentication on their own account will be asked to set it up when they next log in.</p>'),
  ('s1', 'Step 1: Confirm you can change it',
   '<p>Only people with full control of the business portfolio can change this setting. If you can’t see it, you may have partial access. Ask a full-control admin, or see our guide on lost admin access.</p>'),
  ('s2', 'Step 2: Turn it on',
   '<p>In Business Suite open <em>Settings</em>, go to <em>Business portfolio info</em>, then <em>Business options</em>, and set <em>Two-factor authentication</em> to <em>Everyone</em>. Save the change.</p>'),
  ('s3', 'Step 3: Help your team set it up',
   '<p>Recommend an authentication app. Each person sets it up in their own account’s security settings. Make sure they save recovery codes in a safe place. For people without a smartphone, a security key is an alternative.</p>'),
  ('s4', 'Step 4: Review your Security Center',
   '<p>Meta’s Security Center for businesses collects recommended protections. Look at it after the change to see what else is worth turning on, such as reviewing admin roles and ad account access.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t make everyone an admin to “avoid hassle.”</strong> Give each person the lowest role they need.</li><li><strong>Don’t share one login</strong> across the team.</li><li><strong>Don’t turn it on during a campaign launch</strong> without warning, since team members may be briefly locked out.</li></ul>'),
  ('after', 'Keeping it effective',
   '<p>Review the list of people each quarter, remove leavers the same day and keep at least two trusted full-control admins. Add a line about two-factor authentication to your onboarding checklist for contractors.</p>')],
 [('Does this affect agencies?', 'People from partner businesses use their own business’s settings. Ask your partners to protect their accounts as well.'),
  ('Can I require it for only some people?', 'The setting applies to everyone in the portfolio. Roles control what each person can see.'),
  ('What if someone loses their device?', 'They’ll need recovery codes or another method. Our guides on lost two-factor access cover the process.')],
 [('Meta Business Help: Require two-factor authentication', 'https://www.facebook.com/business/help/280940009201586'), ('Meta Business Help: Security Center', 'https://www.facebook.com/business/help/216940652189296'), BIZ_HELP],
 [('/guides/meta-business-portfolio-lost-admin-access/', 'Lost admin access to a portfolio'), ('/guides/meta-agency-partner-access/', 'Give an agency access safely'), ('/guides/instagram-business-vs-creator-account/', 'Business vs creator accounts')],
 ['/guides/meta-business-portfolio-restricted/', '/guides/instagram-business-vs-creator-account/'],
 'I want to secure my Meta business portfolio and require two-factor authentication', 'Meta business portfolio security',
 ('Locking down your portfolio?', 'Ask us what to check', 'We’ll give you a short checklist for roles, access and two-factor.'),
 ('Already locked out?', 'We’ll help you find the route', 'Message us what happened and we’ll point you to the right official step.'),
 **AD))

A(mk('meta-business-portfolio-lost-admin-access',
 'Lost admin access to your Meta business portfolio: what are your options?',
 'Lost Admin Access to a Meta Business Portfolio',
 'Locked out of a business portfolio because the admin left or the account was hacked? Use the official full-control request and prepare proof.',
 'ads', 'Access', None,
 'ask a current full-control admin to add you. If nobody can, use Meta’s request for full control through Business Support Home and have ID and business proof ready.',
 'A portfolio holds your Pages, ad accounts, catalogs and payment information. Losing admin access stops everything, and the longer it lasts, the more risk to your assets.',
 [('first', 'What to do first',
   '<p>Find out who still has access. Check old invitation emails, ask staff and agencies, and look at who’s listed on your Pages. Contact them with a clear written request to be made a full-control admin.</p>'),
  ('s1', 'Step 1: Check you’re logged in correctly',
   '<p>Make sure you’re using the personal profile that was originally invited. A different login or a work email might show nothing. Try opening Business Settings directly from the profile that you used to manage ads.</p>'),
  ('s2', 'Step 2: Request full control',
   '<p>Meta’s help center explains how to request full control of a business portfolio if there’s no admin who can grant it. Expect to confirm your identity and give evidence that you represent the business.</p>'),
  ('s3', 'Step 3: If the portfolio was hacked',
   '<p>If someone else has taken control, use Meta’s hacked business portfolio steps. Secure your personal profile first, because that’s usually how access is lost. Then check ad accounts for charges you didn’t make and contact your bank about any.</p>'),
  ('s4', 'Step 4: Prepare documents',
   '<p>Typical items include government ID, business registration, domain or tax records, invoices connected to ads and a signed letter. Names must be consistent across documents.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t set up a duplicate portfolio</strong> and try to move assets informally. Assets can’t be reassigned without access.</li><li><strong>Don’t pay anyone who promises to “recover” the portfolio.</strong></li><li><strong>Don’t delay</strong> if ad accounts are still billing.</li></ul>'),
  ('after', 'Prevention',
   '<p>Keep two or more full-control admins, tied to different real people. Record the date each role was assigned and review them whenever staff change.</p>')],
 [('Can Meta restore access without documents?', 'Not through official channels. Expect to prove who you are.'),
  ('What if the admin refuses?', 'If you own the business, the official request for full control is the route. Keep your messages as a record.'),
  ('Will I lose my ad history?', 'Not by asking for access. The assets stay with the portfolio.')],
 [('Meta Business Help: Request full control', 'https://www.facebook.com/business/help/474856681929983'), ('Meta Business Help: Hacked business portfolio', 'https://www.facebook.com/business/help/25302697499431030'), ('Meta Business Support Home', 'https://www.facebook.com/business/help/254088759757736')],
 [('/guides/facebook-page-admin-access-lost/', 'Lost access to a Facebook Page'), ('/guides/meta-business-portfolio-restricted/', 'Business portfolio restricted'), ('/business-manager-disabled/', 'Business Manager disabled')],
 ['/guides/meta-business-portfolio-restricted/', '/business-manager-disabled/'],
 'I lost admin access to my Meta business portfolio and need to get it back', 'Meta business portfolio access lost',
 ('No admin left?', 'Tell us the situation', 'Share what you can see and who has access. We’ll point you to the right route.'),
 ('Need help with the request?', 'We’ll help you prepare it', 'Message us. We’ll help you gather proof. No passwords.'),
 **AD))

A(mk('meta-agency-partner-access',
 'Give an agency access to your Meta ads without sharing your login',
 'Give an Agency Access to Meta Ads Safely',
 'How to share Pages and ad accounts with an agency or freelancer as a partner, keep ownership and remove access when the work ends.',
 'ads', 'Partners', None,
 'add the agency as a partner in your business portfolio and share only the assets they need, with the lowest permission that works. Never hand over your own login.',
 'Sharing a password is the fastest way to lose control of an ad account. Meta’s partner access lets an agency work on your assets while you keep ownership and can end the arrangement in a click.',
 [('first', 'What to do first',
   '<p>Make sure your assets live in a business portfolio that <strong>you</strong> own, and that you have full control. Then ask the agency for their <strong>business portfolio ID</strong>, which you’ll need for the invitation. If they don’t have one, they should create it.</p>'),
  ('s1', 'Step 1: Decide what to share',
   '<p>List the Pages, ad accounts, pixels or datasets and catalogs the agency needs. Share only those. If they’re only running ads, they might not need access to your Page inbox or your payment settings.</p>'),
  ('s2', 'Step 2: Add the partner',
   '<p>In Business Settings find <em>Partners</em>, choose to add a partner and enter their business ID. Select the assets and set a permission level for each. Menu labels shift between Meta tools, so look for the partner and asset-sharing options.</p>'),
  ('s3', 'Step 3: Pick the lowest permission that works',
   '<p>For ad accounts, “manage campaigns” is usually enough. Give admin-level access only when needed. For Pages, avoid full control unless the agency is taking over the page entirely.</p>'),
  ('s4', 'Step 4: Keep payment under your control',
   '<p>Use your own payment method on your ad account so spend is under your name. If the agency prefers to bill through its own line of credit, get the terms in writing, including who owns the account and what happens at the end of the contract.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t give the agency your Facebook password.</strong></li><li><strong>Don’t let the agency create the ad account in their portfolio</strong> if you want to own the history. It’s hard to move later.</li><li><strong>Don’t leave access in place after the contract ends.</strong></li></ul>'),
  ('after', 'Ending the relationship',
   '<p>Open the partner list and remove the agency’s access, then check the Pages and ad accounts for any lingering roles. Change shared tool passwords and confirm any pixels or conversion data remain with your portfolio.</p>')],
 [('Does the agency see my payment details?', 'Not by default. Payment methods are separate from asset permissions, so check settings.'),
  ('Can I take ad history with me?', 'It stays with the ad account. That’s why you should keep ownership of the account.'),
  ('What if the agency wants my login?', 'Say no and offer partner access. Any reputable agency can work this way.')],
 [('Meta Business Help: Add or remove a partner', 'https://www.facebook.com/business/help/'), ('Meta Business Help: Security Center', 'https://www.facebook.com/business/help/216940652189296'), BIZ_HELP],
 [('/guides/meta-business-portfolio-two-factor/', 'Business portfolio two-factor'), ('/guides/meta-business-portfolio-lost-admin-access/', 'Lost admin access'), ('/guides/facebook-page-admin-access-lost/', 'Lost access to a Facebook Page')],
 ['/guides/meta-business-portfolio-restricted/'],
 'I want to give an agency access to my Meta ads safely', 'Meta agency access',
 ('Hiring an agency?', 'Ask us how to set it up', 'We’ll give you a short, safe checklist for roles and permissions.'),
 ('Agency locked you out?', 'We’ll look at your options', 'Message us the situation. We’ll point you to the official route.'),
 **AD))

A(mk('meta-special-ad-categories',
 'Meta Special Ad Categories: when you must declare and what changes',
 'Meta Special Ad Categories: When to Declare',
 'Housing, employment, credit and social issue ads need a Special Ad Category. What it limits, why declaring correctly matters and how to fix a wrong choice.',
 'ads', 'Policy', None,
 'if your ad is about credit, employment, housing or social issues, elections or politics, declare the matching Special Ad Category when you create the campaign.',
 'Special Ad Categories exist to prevent discrimination and to make political ads transparent. Declaring correctly is part of running these ads. Not declaring is a common reason for rejections and account problems.',
 [('first', 'What to do first',
   '<p>Check whether the ad is about one of the four areas: financial products and services (credit), employment, housing, or social issues, elections or politics. If you’re unsure, read the policy page for each area and then decide. If any applies, declare it when you create the campaign.</p>'),
  ('s1', 'Step 1: Understand the categories',
   '<p>The categories are credit, employment, housing, and social issues, elections or politics. Examples include job listings, mortgage offers, rental homes, and ads on a political topic or candidate. Meta’s help center lists what counts, and the list is more detailed than these headings.</p>'),
  ('s2', 'Step 2: Expect targeting limits',
   '<p>For credit, employment and housing ads in the US, Canada and some European locations, Meta restricts targeting. Typically you can’t narrow by gender, a specific age range or detailed location such as a postcode, and audience tools including lookalikes are limited. Check the live help page for the rules for your location.</p>'),
  ('s3', 'Step 3: Political and social issue ads',
   '<p>Ads about social issues, elections or politics need advertiser authorisation, a “Paid for by” disclaimer and appear in the Ad Library. Meta stopped serving political, electoral and social issue ads in the EU from 6 October 2025. If you target the EU, check the current policy before you plan.</p>'),
  ('s4', 'Step 4: Fix a wrong choice',
   '<p>If you didn’t declare when you should have, Meta may reject the ad or restrict the account. Edit or create a new campaign with the right category. If you declared by mistake, you may lose targeting options needlessly; create a new campaign without it, as long as your ad truly isn’t in a category.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t avoid declaring to keep targeting options.</strong> That’s circumvention and can disable the account.</li><li><strong>Don’t phrase a housing ad as something else</strong> to dodge the category.</li><li><strong>Don’t run political ads without authorisation.</strong></li></ul>')],
 [('Is every job ad a Special Ad Category?', 'Employment ads that promote job opportunities generally are. Check the policy for what counts.'),
  ('Why did my audience shrink?', 'Targeting limits apply in the categories for certain countries.'),
  ('Can I appeal a wrong rejection?', 'Yes. Request a review and explain why the ad isn’t in the category.')],
 [('Meta Business Help: About Special Ad Categories', 'https://www.facebook.com/business/help/298000447747885'), ('Meta Business Help: Ads about social issues, elections or politics', 'https://www.facebook.com/business/help/837655677217892'), ADS],
 [('/guides/ad-account-circumventing-systems/', 'Ad account and circumvention'), ('/guides/meta-ad-rejected-request-review/', 'Ad rejected, request review'), ('/ad-account-policy-violation-appeal/', 'Ad policy violation appeal')],
 ['/guides/ad-account-unacceptable-business-practices/'],
 'I am not sure whether my ads need a Special Ad Category and want advice', 'Meta Special Ad Categories',
 ('Not sure if it applies?', 'Tell us what you advertise', 'Describe the ad and we’ll tell you what to check in Meta’s policy.'),
 ('Account restricted over it?', 'We’ll help plan the appeal', 'Message us the notice. We’ll help with an honest, accurate appeal.'),
 **AD))

A(mk('meta-ads-health-wellness-personal-attributes',
 'Meta ads for health and wellness: the “personal attributes” trap',
 'Meta Health & Wellness Ads: The Personal Attributes Rule',
 'Why health, weight and wellness ads get rejected for implying knowledge of the viewer, and how to rewrite them within Meta’s policies.',
 'ads', 'Policy', None,
 'don’t write ads that assert or imply you know something about the viewer, such as a health condition. Describe the product or service instead and follow the health and wellness rules.',
 'Health and wellness is one of the most-rejected categories. The most common cause isn’t the product but the phrasing. “Struggling with your weight?” can break a rule that has nothing to do with whether the claim is true.',
 [('first', 'What to do first',
   '<p>Read the rejected ad out loud and underline every phrase that speaks to the viewer about their body, health, finances or personal life. Phrases like “Are you diabetic?” or “Your anxiety is holding you back” suggest you know something about them, and that’s what the personal attributes policy is aimed at.</p>'),
  ('s1', 'Step 1: Learn the two policies that apply',
   '<p>Meta’s ad standards include a policy on personal attributes and a policy on health and wellness. The first says ads shouldn’t assert or imply that you know a person’s attributes such as a health condition. The second covers things like age targeting for weight-loss content and rules on before-and-after imagery and language about body image.</p>'),
  ('s2', 'Step 2: Rewrite from “you” to “the product”',
   '<p>Instead of “Do you suffer from back pain?”, describe the offer: “Physiotherapy sessions for back and posture.” Keep the benefit focused on what the service is, not on a condition the reader supposedly has. Avoid language that implies inferiority about appearance.</p>'),
  ('s3', 'Step 3: Check targeting and images',
   '<p>Weight-loss and similar products typically require targeting adults only. Before-and-after images are restricted in some categories, and rules have been changing, so check the current version of the policy. Avoid close-ups of body parts that stress a perceived flaw.</p>'),
  ('s4', 'Step 4: Be careful with claims',
   '<p>Don’t promise cures or specific results. Use accurate descriptions of what a product does, and make sure the landing page matches the ad.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t try to disguise the product</strong> with unrelated images. That can break other policies.</li><li><strong>Don’t resubmit the same copy</strong> with only small word changes.</li><li><strong>Don’t use fake testimonials</strong> or invented results.</li></ul>')],
 [('Can I mention a condition at all?', 'You can describe a product for a condition in neutral terms, but not imply you know the viewer has it. Check current policy details.'),
  ('Do these rules apply to organic posts?', 'Ad policies apply to ads. Organic content falls under Community Standards.'),
  ('Do before and after images work?', 'Rules vary by category and change over time. Check the live policy before you use them.')],
 [('Meta Advertising Standards: Personal attributes', 'https://transparency.meta.com/policies/ad-standards/'), ('Meta Business Help: Health and wellness ads', 'https://www.facebook.com/business/help/2489235377779939'), BIZ_HELP],
 [('/guides/meta-ad-rejected-request-review/', 'Ad rejected, request review'), ('/guides/ad-account-unacceptable-business-practices/', 'Ad account and unacceptable practices'), ('/guides/meta-ads-landing-page-rejected/', 'Landing page rejected')],
 ['/guides/meta-ad-account-restricted/'],
 'My health or wellness ad keeps getting rejected for personal attributes and I want help rewriting it', 'Meta health ad rejected',
 ('Ad rejected again?', 'Send us the copy', 'Share the ad text and rejection reason and we’ll tell you where we’d look.'),
 ('Account restricted?', 'We’ll help plan the appeal', 'Message us the notice and the ad. We use official routes.'),
 **AD))

A(mk('meta-ads-landing-page-rejected',
 'Meta ad rejected because of your landing page: how to find the problem',
 'Meta Ad Rejected for Landing Page? How to Fix',
 'Ads can be rejected because of what’s on the page you link to. Test it like a reviewer, fix common problems and request a review.',
 'ads', 'Landing page', None,
 'open the exact URL from the ad on a phone, check it loads without errors and matches what the ad promised, then fix what you find and request a review.',
 'Meta reviews the page behind your ad as well as the ad itself. A broken or mismatched page can be rejected even when the creative is spotless.',
 [('first', 'What to do first',
   '<p>Don’t guess. Copy the exact destination URL from the ad in Ads Manager, paste it into a private browser window on your phone, and use mobile data instead of your office Wi-Fi. That’s as close as you’ll get to what a reviewer sees.</p>'),
  ('s1', 'Step 1: Check the basics',
   '<ul><li>Does the page load, without a 404 or server error?</li><li>Does it work without logging in?</li><li>Does it avoid forcing a file download or opening unexpected pop-ups?</li><li>Does the domain match the one in the ad?</li><li>Does the page load quickly on mobile?</li></ul>'),
  ('s2', 'Step 2: Compare the ad to the page',
   '<p>Look for mismatches in price, product, offer and claims. If your ad says “free trial” the page must show it. If the ad shows a product, it must be available there. If you changed the offer, update the ad as well.</p>'),
  ('s3', 'Step 3: Check the content on the page',
   '<p>Check the page against the ad policies, not only the ad. Look for prohibited products, unproven claims, missing business information such as contact details, return terms and privacy policy, or elements that prompt for unnecessary personal data.</p>'),
  ('s4', 'Step 4: Fix and request review',
   '<p>Fix the page first, then request a review from Ads Manager or Account Quality. Leave the ad unchanged while the review is pending.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t show reviewers a different page from what real users see.</strong> That’s cloaking, and it’s a serious violation.</li><li><strong>Don’t redirect through unrelated sites.</strong></li><li><strong>Don’t change the domain mid-review</strong> without updating the ad.</li></ul>'),
  ('after', 'Keeping landing pages healthy',
   '<p>Test top landing pages weekly, and after every site update. A checkout plugin update or expired certificate can break a page overnight, and a rejection follows.</p>')],
 [('Can a slow page cause a rejection?', 'Rejections are usually for errors, mismatch or policy issues. A slow page hurts results even if it’s not rejected.'),
  ('Do I need a privacy policy?', 'If you collect personal data, you should have one. Check policy requirements for your offer.'),
  ('Why was the ad approved last month?', 'Policies and pages change. Re-check both.')],
 [('Meta Business Help: Troubleshoot a rejected ad', 'https://www.facebook.com/business/help/1210227555661027'), ADS, BIZ_HELP],
 [('/guides/meta-ad-rejected-request-review/', 'Ad rejected, request review'), ('/guides/meta-domain-verification-steps/', 'Domain verification'), ('/guides/ad-account-circumventing-systems/', 'Ad account and circumvention')],
 ['/guides/ad-account-circumventing-systems/'],
 'My Meta ad was rejected for the landing page and I am not sure what is wrong with it', 'Meta landing page rejected',
 ('Page flagged?', 'Send us the URL', 'Share the landing page and the rejection and we’ll tell you what we’d check.'),
 ('Need a second look?', 'We’ll review it with you', 'Message us the details. We use official routes only.'),
 **AD))

A(mk('meta-account-quality-status-walkthrough',
 'Meta Account Quality: how to read your ad account and Page status',
 'Meta Account Quality: How to Read Your Status',
 'Where to see restrictions, disapproved ads and review options for your ad account, Page and business portfolio in Meta Account Quality.',
 'ads', 'Account status', None,
 'open business.facebook.com/accountquality, pick the business portfolio and read each asset’s status. Anything with a review option can be requested from there.',
 'Account Quality is Meta’s status dashboard for advertisers. It’s the first place to check when ads stop, because it lists what’s wrong and what you can do about it.',
 [('first', 'What to do first',
   '<p>Log in with the profile that manages the business portfolio and open Account Quality. If you don’t see the portfolio you expect, you may be logged into the wrong profile, or you may not have a role.</p>'),
  ('s1', 'Step 1: Choose the right portfolio',
   '<p>Use the selector at the top to switch between portfolios. Each portfolio has its own status, with sections for the portfolio, ad accounts, Pages and Instagram accounts.</p>'),
  ('s2', 'Step 2: Read the status labels',
   '<p>Look for restrictions, disabled assets, ad rejections and warnings. Meta’s Account Overview in Ads Manager shows a similar view. Open each item to see the policy and the options. Items you can dispute show a request review button.</p>'),
  ('s3', 'Step 3: Request a review once',
   '<p>Where a button exists, use it, add context if there’s a text box and submit. Meta doesn’t publish a timeline for these, so expect updates in the same place and by notification.</p>'),
  ('s4', 'Step 4: Record what you see',
   '<p>Keep dated screenshots of statuses and decisions. They help when you talk to your team or write an appeal.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t request multiple reviews</strong> for the same item.</li><li><strong>Don’t make major changes to a restricted account</strong> until you understand why.</li><li><strong>Don’t share your login</strong> to ask someone to check it for you.</li></ul>'),
  ('after', 'Making it routine',
   '<p>Check Account Quality weekly if you spend heavily on ads, and after any new restriction email. A short routine avoids surprises.</p>')],
 [('Where do I find ad account status?', 'In Account Quality and the Account Overview in Ads Manager.'),
  ('Why can’t I request a review?', 'Not every decision can be reviewed. The page shows the options available.'),
  ('Who can see Account Quality?', 'People with the right role in the business portfolio.')],
 [('Meta Account Quality', 'https://business.facebook.com/accountquality'), ('Meta Business Help: Account overview', 'https://www.facebook.com/business/help/149770628855079'), BIZ_HELP],
 [('/guides/meta-ad-account-restricted/', 'Ad account restricted'), ('/guides/meta-ad-rejected-request-review/', 'Ad rejected, request review'), ('/ad-account-request-review-not-showing/', 'Request review not showing')],
 ['/guides/meta-ad-account-restricted/', '/ad-account-request-review-not-showing/'],
 'I need help reading my Meta Account Quality status', 'Meta Account Quality',
 ('Status confusing?', 'Send a screenshot', 'We’ll explain what it says and what we’d do.'),
 ('No review button?', 'We’ll look at your options', 'Message us the account ID and what you see. We use official routes only.'),
 **AD))
